class Solution:
    def isValid(self, s: str) -> bool:
        stack = []
        for char in s:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack or stack.pop() != "(":
                    return False
        return len(stack) == 0

    def balance_brackets(self, s: str) -> str:
        """ return a string s with all brackets balanced (same number of opening and closing brackets).
        """
        stack = []
        balanced_s = ""
        for char in s:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if stack:
                    balanced_s += stack.pop()
        # Add any leftover opening brackets
        balanced_s += "".join(stack)
        return balanced_s

    def removeOuterParentheses(self, s: str) -> str:
        """return a string s with all outer parentheses removed (first and last opening brackets, and the brackets between them)
        """
        stack = []
        result = []
        for char in s:
            if char == "(":
                stack.append(char)
                result.append(char)
            elif char == ")":
                stack.pop()
                result.append(char)
                # Remove the last character if it's a closing bracket and there are still opening brackets in the stack
                if stack and result[-1] == ")":
                    result.pop()
        return "".join(result)

    def replace_vowels(self, s: str) -> str:
        """ return a string s with all vowels replaced by '*'.
        """
        vowels = "aeiouAEIOU"
        replaced_s = ""
        for char in s:
            if char in vowels:
                replaced_s += "*"
            else:
                replaced_s += char
        return replaced_s

    def filter_strings(self, strings: List[str]) -> List[str]:
        """ return a list of strings from the input list that have a balance of brackets and vowels replaced by '*'.
        """
        result = []
        for s in strings:
            if self.isValid(s) and self.replace_vowels(s).count("*") == self.replace_vowels(s).replace(")", "(").replace("(", ")").count(")"):
