import random
class Solution:
    def getLeastNumbers(self, arr: List[int], k: int) -> List[int]:
        def quick_select(left, right):
            pivot_index = left + random.randint(0, right - left + 1)
            pivot = arr[pivot_index]
            arr[pivot_index], arr[right] = arr[right], arr[pivot_index]

            smaller, larger = left, right - 1
            while smaller < larger:
                while smaller < larger and arr[smaller] <= pivot:
                    smaller += 1
                while smaller < larger and arr[larger] > pivot:
                    larger -= 1
                if smaller < larger:
                    arr[smaller], arr[larger] = arr[larger], arr[smaller]

            arr[smaller], arr[right] = arr[right], arr[smaller]
            if smaller == k:
                return smaller
            elif smaller < k:
                return quick_select(smaller + 1, right)
            else:
                return quick_select(left, smaller - 1)

        n = len(arr)
        if n <= k:
            return arr
        index = quick_select(0, n - 1)
        return arr[:index + 1]

